export function clearEventMemoryForTests() {
  memory.clear(); memoryBytes = 0; pendingDisk.clear();
  if (flushTimer != null) clearTimeout(flushTimer);
  flushTimer = null;
}

export async function readArtifact(key) {
  const full = `artifact:${CURRENT_SCHEMA_HASH}:${key}`;
  return recall(full);
}
export function writeArtifact(key, value) { remember(`artifact:${CURRENT_SCHEMA_HASH}:${key}`, value); }
